package io.github.deepseekbridge;
import android.app.Application;import android.content.Context;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.interfaces.RSAPublicKey;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import javax.crypto.spec.SecretKeySpec;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk={26,33},manifest=Config.NONE,application=Application.class)
public class OpenAiAccountsTest {
 static KeyPair pair;JSONObject jwks;OpenAiAccounts account;LocalState vault;final AtomicInteger exchanges=new AtomicInteger();String nonce,client="oaiapp_fixture",subject="fixture-sub",email="fixture@example.test";boolean revokeFailure;
 @Before public void setup()throws Exception{if(pair==null){KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);pair=g.generateKeyPair();}RSAPublicKey publicKey=(RSAPublicKey)pair.getPublic();jwks=new JSONObject().put("keys",new JSONArray().put(new JSONObject().put("kid","fixture-key").put("kty","RSA").put("alg","RS256").put("n",OpenAiAccounts.b64(unsigned(publicKey.getModulus().toByteArray()))).put("e",OpenAiAccounts.b64(unsigned(publicKey.getPublicExponent().toByteArray())))));Context c=RuntimeEnvironment.getApplication();vault=new LocalState(new EncryptedStateStore(new File(c.getCacheDir(),"account-"+UUID.randomUUID()+".enc"),new SecretKeySpec(new byte[32],"AES")));account=new OpenAiAccounts(vault,this::network,event->{});}
 @After public void cleanup(){account.close();}
 static byte[] unsigned(byte[] input){return input[0]==0?Arrays.copyOfRange(input,1,input.length):input;}
 String jwt(String aud,String n,String sub,long expires)throws Exception{String h=OpenAiAccounts.b64(new JSONObject().put("alg","RS256").put("kid","fixture-key").toString().getBytes(StandardCharsets.UTF_8)),p=OpenAiAccounts.b64(new JSONObject().put("iss",OpenAiAccounts.ISSUER).put("sub",sub).put("email",email).put("aud",aud).put("exp",expires).put("nonce",n).toString().getBytes(StandardCharsets.UTF_8));Signature s=Signature.getInstance("SHA256withRSA");s.initSign(pair.getPrivate());s.update((h+"."+p).getBytes(StandardCharsets.US_ASCII));return h+"."+p+"."+OpenAiAccounts.b64(s.sign());}
 JSONObject network(String url,String method,String body)throws Exception {if(url.endsWith("openid-configuration"))return new JSONObject().put("issuer",OpenAiAccounts.ISSUER).put("jwks_uri",OpenAiAccounts.ISSUER+"/.well-known/jwks.json").put("revocation_endpoint",OpenAiAccounts.ISSUER+"/revoke");if(url.endsWith("jwks.json"))return jwks;if(url.endsWith("/revoke")){if(revokeFailure)throw new IOException("fixture network outage");return new JSONObject();}Map<String,String> fields=OpenAiAccounts.query(body);assertEquals(OpenAiAccounts.RESOURCE,fields.get("resource"));assertFalse(fields.containsKey("client_secret"));exchanges.incrementAndGet();JSONObject result=new JSONObject().put("access_token","fixture-access-"+exchanges.get()).put("refresh_token","fixture-refresh-"+exchanges.get()).put("scope","openid email resource.invoke chatgpt.tokens.use.direct offline_access").put("token_type","Bearer").put("expires_in",3600);if(fields.get("grant_type").equals("authorization_code")){assertEquals(client,fields.get("client_id"));assertFalse(fields.get("client_id").equals("dynamic_agent_client"));assertTrue(fields.get("code_verifier").length()>=43);result.put("id_token",jwt(client,nonce,subject,System.currentTimeMillis()/1000+3600));}else{assertEquals("refresh_token",fields.get("grant_type"));assertFalse(fields.containsKey("scope"));}return result;}
 OpenAiAccounts.Attempt begin(String id)throws Exception {JSONObject result=account.begin(id);assertFalse(result.has("url"));Map<String,String> q=OpenAiAccounts.query(new URI(account.pendingUrl()).getRawQuery());nonce=q.get("nonce");java.lang.reflect.Field f=OpenAiAccounts.class.getDeclaredField("pending");f.setAccessible(true);return (OpenAiAccounts.Attempt)f.get(account);}
 String login()throws Exception {OpenAiAccounts.Attempt a=begin("");account.complete(a,new LinkedHashMap<String,String>(){{put("state",a.state);put("client_id",client);put("code","fixture-code");}});account.cancel();return account.snapshot().getJSONArray("accounts").getJSONObject(account.snapshot().getJSONArray("accounts").length()-1).getString("id");}
 @Test public void realLoopbackCallbackRejectsWrongStateThenCompletesTheValidAttempt()throws Exception {OpenAiAccounts.Attempt a=begin("");URI callback=new URI(a.redirect);for(boolean valid:new boolean[]{false,true}){try(Socket socket=new Socket("127.0.0.1",callback.getPort())){socket.setSoTimeout(5000);String path="/auth/callback?code=fixture-code&client_id="+client+"&state="+(valid?a.state:"wrong");socket.getOutputStream().write(("GET "+path+" HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));socket.getOutputStream().flush();String status=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.UTF_8)).readLine();assertTrue(status,status.contains(valid?"200":"400"));}}assertEquals(1,exchanges.get());assertEquals(1,account.snapshot().getJSONArray("accounts").length());}
 @Test public void firstRegistrationUsesLoopbackPkceAndOnlyPublishesSafeAccountMetadata()throws Exception{OpenAiAccounts.Attempt a=begin("");Map<String,String> q=OpenAiAccounts.query(new URI(account.pendingUrl()).getRawQuery());assertEquals("dynamic_agent_client",q.get("client_id"));assertEquals("DeepSeek Studio",q.get("agent_name_hint"));assertTrue(q.get("ext_agent_host_id").startsWith("urn:uuid:"));assertTrue(q.get("redirect_uri").matches("http://127\\.0\\.0\\.1:[0-9]+/auth/callback"));assertEquals(OpenAiAccounts.b64(MessageDigest.getInstance("SHA-256").digest(a.verifier.getBytes(StandardCharsets.US_ASCII))),q.get("code_challenge"));account.complete(a,new LinkedHashMap<String,String>(){{put("state",a.state);put("client_id",client);put("code","fixture-code");}});assertTrue(account.snapshot().getJSONArray("accounts").getJSONObject(0).getBoolean("canInfer"));String safe=account.snapshot().toString();assertFalse(safe.contains("fixture-access"));assertFalse(safe.contains("fixture-refresh"));assertFalse(safe.contains("id_token"));}
 @Test public void wrongStateDeniedConsentAndMissingIssuedClientNeverExchangeTokens()throws Exception{OpenAiAccounts.Attempt a=begin("");for(Map<String,String> params:Arrays.asList(new HashMap<String,String>(){{put("state","wrong");put("code","fixture");put("client_id",client);}},new HashMap<String,String>(){{put("state",a.state);put("error","access_denied");}},new HashMap<String,String>(){{put("state",a.state);put("code","fixture");}})){try{account.complete(a,params);fail("Invalid callback accepted");}catch(IOException expected){}}assertEquals(0,exchanges.get());}
 @Test public void idTokenRequiresRealSignatureAudienceIssuerNonceAndExpiration()throws Exception {long now=System.currentTimeMillis()/1000;String valid=jwt(client,"nonce",subject,now+3600);assertEquals(subject,OpenAiAccounts.verifyIdToken(valid,jwks,client,"nonce",now).getString("sub"));for(String token:Arrays.asList(jwt("other","nonce",subject,now+3600),jwt(client,"wrong",subject,now+3600),jwt(client,"nonce",subject,now-120),valid.substring(0,valid.length()-6)+"AAAAAA")){try{OpenAiAccounts.verifyIdToken(token,jwks,client,"nonce",now);fail("Unverified identity accepted");}catch(Exception expected){}}}
 @Test public void reauthorizationRetainsClientAndHostAndRejectsAnotherIdentity()throws Exception{String id=login(),host=new JSONObject(vault.load()).getString("host");OpenAiAccounts.Attempt a=begin(id);Map<String,String> q=OpenAiAccounts.query(new URI(account.pendingUrl()).getRawQuery());assertEquals(client,q.get("client_id"));assertEquals(host,q.get("ext_agent_host_id"));assertFalse(q.containsKey("agent_name_hint"));assertTrue(q.containsKey("id_token_hint"));subject="different-account";try{account.complete(a,new HashMap<String,String>(){{put("state",a.state);put("code","fixture");}});fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("不一致"));}assertEquals("fixture-sub",new JSONObject(vault.load()).getJSONArray("accounts").getJSONObject(0).getString("subject"));}
 @Test public void sameEmailRegistrationsStaySeparateAndLogoutRetainsTheClientMapping()throws Exception{String first=login();client="oaiapp_another";String second=login();assertNotEquals(first,second);assertEquals(2,account.snapshot().getJSONArray("accounts").length());revokeFailure=true;JSONObject state=account.logout(first);assertTrue(state.getString("notice").contains("未确认"));JSONArray saved=new JSONObject(vault.load()).getJSONArray("accounts");assertEquals("oaiapp_fixture",saved.getJSONObject(0).getString("client_id"));assertFalse(saved.getJSONObject(0).has("refresh_token"));assertTrue(saved.getJSONObject(1).has("refresh_token"));}
 @Test public void rotatingRefreshIsSerializedAndSavedAtomically()throws Exception{String id=login();JSONObject saved=new JSONObject(vault.load());saved.getJSONArray("accounts").getJSONObject(0).put("expiresAt",1);assertTrue(vault.save(saved.toString()));account.close();account=new OpenAiAccounts(vault,this::network,event->{});ExecutorService pool=Executors.newFixedThreadPool(3);try{List<Future<String>> results=new ArrayList<>();for(int i=0;i<3;i++)results.add(pool.submit(()->account.access(id)));for(Future<String> value:results)assertEquals("fixture-access-2",value.get(3,TimeUnit.SECONDS));assertEquals(2,exchanges.get());assertEquals("fixture-refresh-2",new JSONObject(vault.load()).getJSONArray("accounts").getJSONObject(0).getString("refresh_token"));}finally{pool.shutdownNow();}}
}
